        if command == 'get_organization':
            return org_get(data)
        if command == 'save_organization':
            return org_save(data)
        if command == 'deactivate_organization':
            return org_deactivate(data)
        fail('error.status')

    result = dispatch('get_approval_workflow')
    frappe.response['message'] = result

