    def notify_step(request, instance):
        if frappe.call('purchase_approval.workflow_runtime.bridge', action='is_modern', request=request):
            current = frappe.call('purchase_approval.workflow_runtime.bridge', action='active_step', instance=instance)
            if current:
                frappe.call('purchase_approval.workflow_runtime.bridge', action='enqueue', request=request, instance=instance, step=current)
            return
        for row in instance.assignees:
            if row.step_order == instance.current_sequence and row.status == 'Pending':
                key = instance.name + ':' + str(row.step_order) + ':' + row.user
                existing = frappe.db.get_value('PA Notification Outbox', {'notification_key': key}, ['name', 'status'], as_dict=True)
                if existing:
                    if existing.status == 'Cancelled':
                        frappe.db.set_value('PA Notification Outbox', existing.name, 'status', 'Pending')
                    continue
                outbox = frappe.get_doc({'doctype': 'PA Notification Outbox', 'request': request.name, 'instance': instance.name, 'step_order': row.step_order, 'recipient': row.user, 'notification_key': key, 'subject': t('notification.subject') + ' ' + request.name, 'body': t('notification.body'), 'status': 'Pending'})
                outbox.insert(ignore_permissions=True)

    def notification_worker():
        if not frappe.db.get_single_value('PA Settings', 'email_enabled'):
            return
        for row in frappe.get_all('PA Notification Outbox', filters={'status': 'Pending', 'attempts': ['<', 5]}, fields=['name'], limit_page_length=100):
            query_lock('select name from `tabPA Notification Outbox` where name=%s for update', (row.name,))
            outbox = locked_doc('PA Notification Outbox', row.name)
            if outbox.status != 'Pending':
                continue
            instance = frappe.get_doc(INST, outbox.instance)
            request = frappe.get_doc(PR, outbox.request)
            active = request.status == 'Pending Approval' and instance.status == 'Pending' and request.current_instance == instance.name and instance.current_sequence == outbox.step_order and eligible(outbox.recipient, request) and any(a.user == outbox.recipient and a.step_order == outbox.step_order and a.status == 'Pending' for a in instance.assignees)
            if not active:
                outbox.status = 'Cancelled'
            else:
                outbox.attempts = int(outbox.attempts or 0) + 1
                try:
                    url = frappe.utils.get_url('/purchase-approval?request=' + request.name)
                    frappe.sendmail(recipients=[outbox.recipient], subject=outbox.subject, message=frappe.utils.escape_html(outbox.body) + '<br><a href="' + frappe.utils.escape_html(url) + '">' + frappe.utils.escape_html(request.name) + '</a>')
                    outbox.status = 'Sent'
                    outbox.sent_at = frappe.utils.now()
                    outbox.last_error = None
                except Exception:
                    outbox.last_error = t('error.email')
            outbox.save(ignore_permissions=True)


    def dispatch(command):
