            had_share_key = 'key' in frappe.form_dict
            old_share_key = frappe.form_dict.get('key')
            share_key_created = False
            try:
                share_key.insert(ignore_permissions=True)
                share_key_created = True
                temporary_key = share_key.key
                # Print permission validates share keys through get_cached_value, which can read from a replica.
                # Commit this read-only request's temporary key before the print permission check.
                frappe.db.commit()
