def pa_execute(doc=None):
    # Shared, import-free source compiled into every Server Script.
    # All business writes use the request lock and Frappe's POST transaction.
    PR = 'PA Purchase Request'
    WF = 'PA Approval Workflow'
    INST = 'PA Approval Instance'
    HIST = 'PA Approval History'
    COMMANDS = ['create_purchase_request', 'save_purchase_request', 'submit_purchase_request', 'finalize_purchase_request', 'approval_action', 'receive_purchase_request', 'cancel_purchase_request', 'reassign_approver', 'choose_approval_workflow', 'confirm_stock_check']
    EDIT_FIELDS = ['request_date', 'required_date', 'purchase_type', 'priority', 'purpose', 'project', 'note']
    LINE_FIELDS = ['product', 'item_code', 'item_name', 'description', 'uom', 'quantity', 'has_estimated_price', 'estimated_unit_price', 'estimated_vat_percent', 'delivery_date', 'note']


    def t(key):
        return frappe.db.get_value('PA Translation', key, 'text') or key


    def document_values(doc):
        # JSON fields use Python's plain JSON encoder on the installed Frappe.
        return json.loads(json.dumps(doc.as_dict(), default=str))


    def query_lock(query, params):
        try:
            return frappe.db.sql(query, params, as_dict=True)
        except Exception:
            fail('error.conflict')


    def locked_doc(doctype, name, lock=True):
        try:
            return frappe.get_doc(doctype, name, for_update=lock)
        except Exception:
            fail('error.conflict')


    def fail(key):
        frappe.throw(t(key))


    def roles_of(user):
        rows = frappe.db.sql("select role from `tabHas Role` where parent=%s and parenttype=%s", (user, 'User'), as_dict=True)
        return [row.role for row in rows]


    def super_user(user):
        return user == 'Administrator' or 'PA Super Admin' in roles_of(user)


    def actor():
        user = frappe.session.user
        if not user or user == 'Guest':
            fail('error.auth')
        if user != 'Administrator' and not frappe.db.get_value('User', user, 'enabled'):
            fail('error.inactive')
        return user


    def permitted_values(user, allow):
        if 'PA Manager' in roles_of(user):
            field = 'company' if allow == 'Company' else 'deparment' if allow == 'Department' else None
            value = frappe.db.get_value('User', user, field) if field else None
            return [value] if value else []
        return [row.for_value for row in frappe.get_all('User Permission', filters={'user': user, 'allow': allow}, fields=['for_value'])]


    def scope(user, company, department=None):
        if not company or not frappe.db.exists('Company', company):
            return False
        if department:
            dep = frappe.db.get_value('Department', department, 'company')
            if dep != company:
                return False
        if super_user(user):
            return True
        companies = permitted_values(user, 'Company')
        departments = permitted_values(user, 'Department')
        return company in companies and (not department or not departments or department in departments)


    def active_scope(user, company, department=None):
        return bool(scope(user, company, department) and frappe.db.get_value('Company', company, 'active') and (not department or frappe.db.get_value('Department', department, 'active')))


    def require_scope(user, company, department=None):
        if not scope(user, company, department):
            fail('error.permission')


    def require_active_scope(user, company, department=None):
        if not active_scope(user, company, department):
            fail('error.permission')


    def has_role(user, role):
        return super_user(user) or role in roles_of(user)


    def require_role(user, role):
        if not has_role(user, role):
            fail('error.permission')


    def can_read(user, request):
        if not scope(user, request.company, request.department):
            return False
        rr = roles_of(user)
        if not super_user(user) and not any(role in rr for role in ['PA Requester', 'PA Manager', 'PA Purchasing', 'PA Approver', 'PA Receiver', 'PA Stock Checker', 'PA Company Admin']) and not (request.current_instance and frappe.db.exists('PA Approval Assignee', {'parent': request.current_instance, 'user': user})) and not (request.status == 'Pending Workflow Selection' and frappe.call('purchase_approval.workflow_runtime.bridge', action='actions', request=request, user=user)):
            return False
        if request.requester == user or super_user(user):
            return True
        if request.status == 'Draft':
            return False
        return any(role in rr for role in ['PA Manager', 'PA Purchasing', 'PA Approver', 'PA Receiver', 'PA Stock Checker', 'PA Company Admin']) or bool(request.current_instance and frappe.db.exists('PA Approval Assignee', {'parent': request.current_instance, 'user': user})) or bool(request.status == 'Pending Workflow Selection' and frappe.call('purchase_approval.workflow_runtime.bridge', action='actions', request=request, user=user))


    def round_div(numerator, denominator):
        return (numerator + denominator // 2) // denominator


    def scaled(value, precision=2, maximum=1000000000000, required=False):
        raw = str(value if value is not None else '').strip()
        if not raw:
            if required:
                fail('error.line')
            return 0
        parts = raw.split('.')
        if len(parts) > 2 or not parts[0].isdigit() or (len(parts) == 2 and parts[1] and not parts[1].isdigit()):
            fail('error.line')
        decimal = parts[1] if len(parts) == 2 else ''
        if len(parts[0]) > 16 or len(decimal) > 12:
            fail('error.line')
        n = int(parts[0]) * (10 ** precision) + int((decimal + '0' * precision)[:precision] or '0')
        if len(decimal) > precision and int(decimal[precision]) >= 5:
            n = n + 1
        if n > maximum * (10 ** precision) or (required and n == 0):
            fail('error.line')
        return n


    def estimate_scaled_amounts(quantity, unit_price, vat_percent):
        gross_unit = round_div(unit_price * (1000000 + vat_percent), 1000000)
        subtotal = round_div(quantity * unit_price, 10000)
        total = round_div(quantity * gross_unit, 10000)
        return {'subtotal': subtotal, 'tax': total - subtotal, 'total': total}


    def estimate_line_amounts(quantity, unit_price, vat_percent, has_estimated_price):
        if not int(has_estimated_price or 0):
            return {'subtotal': 0, 'tax': 0, 'total': 0}
        quantity_scaled = scaled(quantity, 4, 100000000, True)
        price_scaled = scaled(unit_price, 2)
        vat_scaled = scaled(vat_percent, 4, 100)
        return estimate_scaled_amounts(quantity_scaled, price_scaled, vat_scaled)


    def estimate_request_values(request_values):
        total = 0
        for line in request_values.get('items') or []:
            amounts = estimate_line_amounts(
                line.get('quantity'), line.get('estimated_unit_price'),
                line.get('estimated_vat_percent'), line.get('has_estimated_price'))
            line['estimated_amount'] = amounts['total'] / 100
            total = total + amounts['total']
        request_values['estimated_total'] = total / 100
        return request_values


    def checked_text(value, max_length, required=False):
        value = str(value or '').strip()
        if len(value) > max_length or (required and not value):
            fail('error.required')
        return value


    def check_date(value):
        try:
            return str(frappe.utils.getdate(value)) if value else None
        except Exception:
            fail('error.required')


    def checked_comment(value, required=True):
        if required and not str(value or '').strip():
            fail('error.comment')
        return checked_text(value, 2000)


    def normalize(request):
        if not request.company or not request.department:
            fail('error.required')
        require_scope(actor(), request.company, request.department)
        if request.purchase_type not in ['Goods', 'Service', 'Asset'] or request.priority not in ['Low', 'Normal', 'High', 'Urgent'] or request.currency != 'VND':
            fail('error.required')
        request.purpose = checked_text(request.purpose, 500, True)
        request.project = checked_text(request.project, 140)
        request.note = checked_text(request.note, 4000)
        if request.selected_workflow:
            selected = frappe.db.get_value(WF, request.selected_workflow, ['company', 'department', 'currency', 'is_active'], as_dict=True)
            if not selected or not selected.is_active or selected.company != request.company or (selected.department and selected.department != request.department) or selected.currency != request.currency:
                fail('error.workflow')
        request.request_date = check_date(request.request_date)
        request.required_date = check_date(request.required_date)
        if not request.request_date or not request.required_date or request.required_date < request.request_date:
            fail('error.required')
        if not request.items or len(request.items) > 100:
            fail('error.lines')
        total = 0
        for line in request.items:
            line.item_name = checked_text(line.item_name, 250, True)
            line.item_code = checked_text(line.item_code, 140)
            line.description = checked_text(line.description, 2000)
            line.note = checked_text(line.note, 2000)
            if not frappe.db.get_value('PA Unit', line.uom, 'is_active'):
                fail('error.line')
            if line.product and not frappe.db.get_value('Product', line.product, 'is_active'):
                fail('error.line')
            qty = scaled(line.quantity, 4, 100000000, True)
            has_estimated_price = int(line.has_estimated_price or 0)
            price = scaled(line.estimated_unit_price, 2) if has_estimated_price else 0
            vat = scaled(line.estimated_vat_percent, 4, 100)
            line.quantity = qty / 10000
            line.estimated_unit_price = price / 100
            line.estimated_vat_percent = vat / 10000
            amounts = estimate_scaled_amounts(qty, price, vat) if has_estimated_price else {'subtotal': 0, 'tax': 0, 'total': 0}
            line.estimated_amount = amounts['total'] / 100
            line.delivery_date = check_date(line.delivery_date)
            total = total + amounts['total']
        if total > 100000000000000:
            fail('error.line')
        request.estimated_total = total / 100


    def internal(doc):
        return bool(doc.flags.get('pa_internal')) and frappe.request.path in ['/api/method/pa_' + cmd for cmd in COMMANDS]


    def persist(doc, new=False):
        doc.flags.pa_internal = True
        if new:
            doc.insert(ignore_permissions=True)
        else:
            doc.save(ignore_permissions=True)
        return doc


    def before_request_save(doc):
        user = actor()
        if internal(doc):
            require_scope(user, doc.company, doc.department)
            return
        fail('error.command_only')


    def lock_request(name, data, write=True):
        if not name or not frappe.db.exists(PR, name):
            fail('error.not_found')
        if write:
            query_lock('select name from `tabPA Purchase Request` where name=%s for update', (name,))
        request = locked_doc(PR, name, write)
        if not can_read(actor(), request):
            fail('error.not_found')
        if write:
            try:
                revision = int(data.get('expected_revision', -1))
            except Exception:
                fail('error.conflict')
            if str(data.get('expected_modified') or '') != str(request.modified) or revision != int(request.revision or 0):
                fail('error.conflict')
        return request


    def audit(request, action, comment='', old=None, sequence=0):
        user = actor()
        history = frappe.get_doc({'doctype': HIST, 'request': request.name, 'company': request.company, 'department': request.department, 'instance': request.current_instance, 'action': action, 'actor': user, 'actor_name': frappe.db.get_value('User', user, 'full_name') or user, 'comment': comment, 'step_order': sequence, 'old_values': old or {}, 'new_values': document_values(request)})
        persist(history, True)


    def editable(request, user):
        require_role(user, 'PA Requester')
        if request.requester != user or request.status not in ['Draft', 'Returned']:
            fail('error.status')


    def apply_input(request, data):
        for field in EDIT_FIELDS:
            if field in data:
                request.set(field, data.get(field))
        if 'selected_workflow' in data:
            request.selected_workflow = data.get('selected_workflow') or None
            request.selection_source = 'Requester' if request.selected_workflow else None
        if 'items' in data:
            if not isinstance(data.get('items'), list) or len(data.get('items')) > 100:
                fail('error.lines')
            request.set('items', [])
            for line in data.get('items'):
                if not isinstance(line, dict):
                    fail('error.line')
                request.append('items', {field: line.get(field) for field in LINE_FIELDS})
        normalize(request)


    def create_request(data):
        user = actor()
        require_role(user, 'PA Requester')
        key = checked_text(data.get('idempotency_key'), 90, True)
        key = checked_text(user + ':' + key, 140, True)
        if not data.get('company') or not data.get('department'):
            fail('error.required')
        require_active_scope(user, data.get('company'), data.get('department'))
        # Serialize creates per company; unique idempotency_key remains a DB guard.
        query_lock('select name from `tabCompany` where name=%s for update', (data.get('company'),))
        existing = query_lock('select name from `tabPA Purchase Request` where idempotency_key=%s for update', (key,))
        if existing:
            request = locked_doc(PR, existing[0].name)
            if not can_read(user, request):
                fail('error.not_found')
            return request_details(request)
        request = frappe.get_doc({'doctype': PR, 'company': data.get('company'), 'department': data.get('department'), 'currency': 'VND', 'priority': 'Normal', 'purchase_type': 'Goods', 'status': 'Draft', 'revision': 0, 'requester': user, 'requester_name': frappe.db.get_value('User', user, 'full_name') or user, 'idempotency_key': key})
        apply_input(request, data)
        persist(request, True)
        audit(request, 'Create')
        return request_details(request)


    def save_request(data):
        request = lock_request(data.get('name'), data)
        editable(request, actor())
        old = document_values(request)
        apply_input(request, data)
        persist(request)
        audit(request, 'Save', old=old)
        return request_details(request)


    def submit_request(data):
        request = lock_request(data.get('name'), data)
        editable(request, actor())
        old = document_values(request)
        normalize(request)
        request.revision = int(request.revision or 0) + 1
        request.status = 'Pending Workflow Selection'
        request.submitted_at = frappe.utils.now()
        request.supplier = None
        request.current_instance = None
        request.priced_at = None
        request.priced_by = None
        for field in ['final_subtotal', 'final_tax', 'final_total']:
            request.set(field, 0)
        for line in request.items:
            for field in ['final_unit_price_net', 'final_unit_price_gross', 'vat_percent', 'final_subtotal', 'final_tax', 'final_amount']:
                line.set(field, 0)
        persist(request)
        frappe.call('purchase_approval.workflow_runtime.bridge', action='start_submitted', request=request)
        audit(request, 'Submit', old=old)
        return request_details(request)

    def workflow_matches(workflow, request):
        return workflow.is_active and workflow.company == request.company and (not workflow.department or workflow.department == request.department) and workflow.currency == request.currency


    def workflows_for(request):
        candidates = []
        for row in frappe.get_all(WF, filters={'company': request.company, 'is_active': 1}, fields=['name'], limit_page_length=500):
            workflow = frappe.get_doc(WF, row.name)
            if workflow_matches(workflow, request):
                candidates.append(workflow)
        return candidates


    def preferred_workflows(request):
        candidates = workflows_for(request)
        if not candidates:
            return []
        specificity = max(1 if workflow.department else 0 for workflow in candidates)
        return [workflow for workflow in candidates if (1 if workflow.department else 0) == specificity]


    def select_workflow(request):
        candidates = preferred_workflows(request)
        if not candidates:
            fail('error.no_workflow')
        if request.selected_workflow:
            matches = [workflow for workflow in candidates if workflow.name == request.selected_workflow]
            if not matches:
                fail('error.workflow')
            workflow = matches[0]
        else:
            if len(candidates) != 1:
                fail('error.ambiguous')
            workflow = candidates[0]
        query_lock('select name from `tabPA Approval Workflow` where name=%s for update', (workflow.name,))
        workflow = locked_doc(WF, workflow.name)
        if not workflow_matches(workflow, request):
            fail('error.workflow')
        return workflow


    def eligible(user, request):
        return bool(user and user != 'Guest' and frappe.db.get_value('User', user, 'enabled') and scope(user, request.company, request.department) and (super_user(user) or any(role in roles_of(user) for role in ['PA Approver', 'PA Manager', 'PA Company Admin'])))


    def step_users(step, request):
        users = []
        if step.approver_source == 'User':
            users = [step.approver_user]
        elif step.approver_source == 'Department Manager':
            users = [row.parent for row in frappe.get_all('Has Role', filters={'role': 'PA Manager', 'parenttype': 'User'}, fields=['parent']) if frappe.db.get_value('User', row.parent, 'deparment') == request.department]
        elif step.approver_source == 'Role':
            users = [row.parent for row in frappe.get_all('Has Role', filters={'role': step.approver_role, 'parenttype': 'User'}, fields=['parent'])]
        users = sorted(set(user for user in users if eligible(user, request)))
        if step.approver_source == 'Department Manager' and users == [request.requester]:
            return []
        users = [user for user in users if user != request.requester]
        if not users:
            fail('error.no_approver')
        return users


    def snapshot_instance(request, workflow):
        instance = frappe.get_doc({'doctype': INST, 'request': request.name, 'company': request.company, 'department': request.department, 'workflow': workflow.name, 'workflow_name': workflow.workflow_name, 'workflow_version': workflow.modified, 'workflow_snapshot': document_values(workflow), 'revision': request.revision, 'status': 'Pending', 'steps': [], 'assignees': []})
        pending = []
        for step in sorted(workflow.steps, key=lambda s: s.step_order):
            if step.step_type and step.step_type != 'Quote Approval':
                continue
            users = step_users(step, request)
            instance.append('steps', {'step_order': step.step_order, 'step_name': step.step_name, 'approval_method': step.approval_method, 'status': 'Pending' if users else 'Skipped'})
            if users:
                pending.append(step.step_order)
            for user in users:
                instance.append('assignees', {'step_order': step.step_order, 'user': user, 'status': 'Pending'})
        if not pending:
            fail('error.no_approver')
        instance.current_sequence = min(pending)
        persist(instance, True)
        return instance


    def finalize_request(data):
        user = actor()
        request = lock_request(data.get('name'), data)
        modern = frappe.call('purchase_approval.workflow_runtime.bridge', action='is_modern', request=request)
        if modern:
            instance = get_instance(request)
            current = frappe.call('purchase_approval.workflow_runtime.bridge', action='active_step', instance=instance)
            if not current or current.step_type != 'Quotation' or not frappe.call('purchase_approval.workflow_runtime.bridge', action='assigned', instance=instance, user=user):
                fail('error.permission')
        else:
            require_role(user, 'PA Purchasing')
        if request.status != 'Pending Purchasing':
            fail('error.status')
        supplier = frappe.get_doc('PA Supplier', data.get('supplier')) if data.get('supplier') and frappe.db.exists('PA Supplier', data.get('supplier')) else None
        if not supplier or not supplier.is_active or request.company not in [row.company for row in supplier.companies]:
            fail('error.supplier')
        prices = data.get('prices') or []
        if not isinstance(prices, list) or not all(isinstance(p, dict) and isinstance(p.get('name'), str) for p in prices):
            fail('error.lines')
        if len(prices) != len(request.items) or sorted([p.get('name') for p in prices]) != sorted([line.name for line in request.items]):
            fail('error.lines')
        old = document_values(request)
        subtotal = 0
        tax = 0
        total = 0
        for line in request.items:
            price = [p for p in prices if p.get('name') == line.name][0]
            net = scaled(price.get('unit_price'), 2, 1000000000000)
            if price.get('unit_price') is None or price.get('unit_price') == '':
                fail('error.line')
            vat = scaled(price.get('vat_percent'), 4, 100)
            qty = scaled(line.quantity, 4, 100000000, True)
            gross = round_div(net * (1000000 + vat), 1000000)
            line_total = round_div(qty * gross, 10000)
            line_subtotal = round_div(qty * net, 10000)
            line.final_unit_price_net = net / 100
            line.final_unit_price_gross = gross / 100
            line.vat_percent = vat / 10000
            line.final_subtotal = line_subtotal / 100
            line.final_amount = line_total / 100
            line.final_tax = (line_total - line_subtotal) / 100
            subtotal = subtotal + line_subtotal
            tax = tax + line_total - line_subtotal
            total = total + line_total
        if total > 100000000000000:
            fail('error.line')
        if not modern:
            if 'selected_workflow' in data:
                request.selected_workflow = data.get('selected_workflow') or None
                request.selection_source = 'Purchasing' if request.selected_workflow else None
            workflow = select_workflow(request)
            request.revision = int(request.revision or 0) + 1
            instance = snapshot_instance(request, workflow)
            request.current_instance = instance.name
        request.final_subtotal = subtotal / 100
        request.final_tax = tax / 100
        request.final_total = total / 100
        request.supplier = supplier.name
        request.priced_by = user
        request.priced_at = frappe.utils.now()
        request.status = 'Pending Approval'
        persist(request)
        if modern:
            frappe.call('purchase_approval.workflow_runtime.bridge', action='finish_step', request=request, instance=instance, user=user)
        else:
            notify_step(request, instance)
        audit(request, 'Finalize', old=old)
        return request_details(request)


    def get_instance(request):
        if not request.current_instance:
            fail('error.status')
        query_lock('select name from `tabPA Approval Instance` where name=%s for update', (request.current_instance,))
        instance = locked_doc(INST, request.current_instance)
        if instance.status != 'Pending' or instance.request != request.name or int(instance.revision) != int(request.revision):
            fail('error.conflict')
        return instance


    def approval_action(data):
        request = lock_request(data.get('name'), data)
        user = actor()
        if request.status != 'Pending Approval':
            fail('error.status')
        if user == request.requester:
            fail('error.self')
        instance = get_instance(request)
        matches = [row for row in instance.assignees if row.step_order == instance.current_sequence and row.user == user and row.status == 'Pending']
        modern = frappe.call('purchase_approval.workflow_runtime.bridge', action='is_modern', request=request)
        if modern and next((s for s in instance.steps if s.step_order == instance.current_sequence), None).step_type != 'Quote Approval':
            fail('error.status')
        if not matches or (not modern and not eligible(user, request)) or (modern and not frappe.call('purchase_approval.workflow_runtime.bridge', action='eligible_user', user=user, request=request)):
            fail('error.permission')
        action = data.get('action')
        if action not in ['Approve', 'Return', 'Reject']:
            fail('error.status')
        comment = checked_comment(data.get('comment'), action != 'Approve')
        old = document_values(request)
        sequence = instance.current_sequence
        assignee = matches[0]
        step = [row for row in instance.steps if row.step_order == sequence][0]
        assignee.status = {'Approve': 'Approved', 'Return': 'Returned', 'Reject': 'Rejected'}[action]
        assignee.comment = comment
        assignee.acted_at = frappe.utils.now()
        if action != 'Approve':
            step.status = assignee.status
            step.completed_at = frappe.utils.now()
            instance.status = assignee.status
            instance.completed_at = frappe.utils.now()
            request.status = assignee.status
            for row in instance.assignees:
                if row.status == 'Pending':
                    row.status = 'Cancelled'
            for row in instance.steps:
                if row.status == 'Pending':
                    row.status = 'Cancelled'
        elif step.approval_method == 'Any' or all(row.status == 'Approved' for row in instance.assignees if row.step_order == sequence and row.status != 'Cancelled'):
            step.status = 'Approved'
            step.completed_at = frappe.utils.now()
            for row in instance.assignees:
                if row.step_order == sequence and row.status == 'Pending':
                    row.status = 'Skipped'
            remaining = [row.step_order for row in instance.steps if row.status == 'Pending']
            if remaining:
                instance.current_sequence = min(remaining)
            else:
                instance.current_sequence = 0
                instance.status = 'Approved'
                instance.completed_at = frappe.utils.now()
                request.status = 'Approved'
        persist(instance)
        persist(request)
        if modern:
            filters = {'instance': instance.name, 'step_order': sequence, 'status': 'Pending'}
            if step.status == 'Pending':
                filters['recipient'] = user
            for pending in frappe.get_all('PA Notification Outbox', filters=filters, fields=['name'], limit_page_length=0):
                frappe.db.set_value('PA Notification Outbox', pending.name, 'status', 'Cancelled', update_modified=False)
        else:
            cancel_notifications(instance.name)
        if modern and action == 'Approve' and step.status == 'Approved':
            frappe.call('purchase_approval.workflow_runtime.bridge', action='advance', request=request, instance=instance)
        elif instance.status == 'Pending':
            notify_step(request, instance)
        audit(request, action, comment, old, sequence)
        return request_details(request)


    def receive_request(data):
        user = actor()
        request = lock_request(data.get('name'), data)
        modern = frappe.call('purchase_approval.workflow_runtime.bridge', action='is_modern', request=request)
        if modern:
            instance = get_instance(request)
            current = frappe.call('purchase_approval.workflow_runtime.bridge', action='active_step', instance=instance)
            if not current or current.step_type != 'Receiving' or not frappe.call('purchase_approval.workflow_runtime.bridge', action='assigned', instance=instance, user=user):
                fail('error.permission')
        else:
            require_role(user, 'PA Receiver')
        if request.status != 'Approved':
            fail('error.status')
        old = document_values(request)
        request.received_by = user
        request.received_at = frappe.utils.now()
        comment = checked_text(data.get('comment'), 2000)
        if modern:
            frappe.call('purchase_approval.workflow_runtime.bridge', action='finish_step', request=request, instance=instance, user=user, comment=comment)
        else:
            request.status = 'Closed'
            persist(request)
        audit(request, 'Receive', comment, old)
        return request_details(request)


    def cancel_request(data):
        request = lock_request(data.get('name'), data)
        user = actor()
        if request.status in ['Closed', 'Rejected', 'Cancelled'] or not ((request.requester == user and has_role(user, 'PA Requester')) or has_role(user, 'PA Company Admin')):
            fail('error.status')
        comment = checked_comment(data.get('comment'))
        old = document_values(request)
        if request.current_instance and request.status in ['Pending Stock Check', 'Pending Purchasing', 'Pending Approval', 'Approved']:
            instance = get_instance(request)
            instance.status = 'Cancelled'
            instance.completed_at = frappe.utils.now()
            for row in instance.steps + instance.assignees:
                if row.status == 'Pending':
                    row.status = 'Cancelled'
            persist(instance)
            cancel_notifications(instance.name)
        request.status = 'Cancelled'
        persist(request)
        audit(request, 'Cancel', comment, old)
        return request_details(request)


    def reassign(data):
        user = actor()
        require_role(user, 'PA Company Admin')
        request = lock_request(data.get('name'), data)
        if request.status != 'Pending Approval':
            fail('error.status')
        comment = checked_comment(data.get('comment'))
        instance = get_instance(request)
        old_user = data.get('from_user')
        new_user = data.get('to_user')
        if new_user == request.requester or not (frappe.call('purchase_approval.workflow_runtime.bridge', action='eligible_user', user=new_user, request=request) if frappe.call('purchase_approval.workflow_runtime.bridge', action='is_modern', request=request) else eligible(new_user, request)):
            fail('error.permission')
        rows = [row for row in instance.assignees if row.step_order == instance.current_sequence and row.user == old_user and row.status == 'Pending']
        if not rows or any(row.user == new_user and row.step_order == instance.current_sequence and row.status in ['Pending', 'Approved'] for row in instance.assignees):
            fail('error.conflict')
        rows[0].status = 'Cancelled'
        instance.append('assignees', {'step_order': instance.current_sequence, 'user': new_user, 'status': 'Pending'})
        persist(instance)
        persist(request)
        audit(request, 'Reassign', comment, {'from_user': old_user, 'to_user': new_user}, instance.current_sequence)
        if frappe.call('purchase_approval.workflow_runtime.bridge', action='is_modern', request=request):
            for pending in frappe.get_all('PA Notification Outbox', filters={'instance': instance.name, 'step_order': instance.current_sequence, 'status': 'Pending'}, fields=['name'], limit_page_length=0):
                frappe.db.set_value('PA Notification Outbox', pending.name, 'status', 'Cancelled', update_modified=False)
        else:
            cancel_notifications(instance.name)
        notify_step(request, instance)
        return request_details(request)


    def request_actions(request):
        user = actor()
        actions = []
        if user == request.requester and has_role(user, 'PA Requester') and request.status in ['Draft', 'Returned']:
            actions = ['save', 'submit']
        dynamic = frappe.call('purchase_approval.workflow_runtime.bridge', action='actions', request=request, user=user)
        if dynamic is None:
            if request.status == 'Pending Purchasing' and has_role(user, 'PA Purchasing'):
                actions.append('finalize')
            if request.status == 'Pending Approval' and request.requester != user and eligible(user, request):
                instance = frappe.get_doc(INST, request.current_instance)
                if any(row.user == user and row.status == 'Pending' and row.step_order == instance.current_sequence for row in instance.assignees):
                    actions.extend(['approve', 'return', 'reject'])
            if request.status == 'Approved' and has_role(user, 'PA Receiver'):
                actions.append('receive')
        else:
            actions.extend(dynamic)
        if request.status not in ['Closed', 'Rejected', 'Cancelled'] and ((user == request.requester and has_role(user, 'PA Requester')) or has_role(user, 'PA Company Admin')):
            actions.append('cancel')
        if request.status == 'Pending Approval' and has_role(user, 'PA Company Admin'):
            actions.append('reassign')
        return actions

    def request_details(request):
        request_values = document_values(request)
        if not request.priced_at:
            request_values = estimate_request_values(request_values)
        result = {'request': request_values, 'actions': request_actions(request)}
        result['history'] = frappe.get_all(HIST, filters={'request': request.name}, fields=['name', 'creation', 'action', 'actor_name', 'comment', 'step_order'], order_by='creation asc', limit_page_length=1000)
        result['instances'] = [document_values(frappe.get_doc(INST, row.name)) for row in frappe.get_all(INST, filters={'request': request.name}, fields=['name'], order_by='revision desc', limit_page_length=100)]
        people = [request.requester, request.received_by]
        for instance in result['instances']:
            people.extend([row.get('user') for row in instance.get('assignees', [])])
        result['labels'] = {
            'company': frappe.db.get_value('Company', request.company, 'company_name') or request.company,
            'department': frappe.db.get_value('Department', request.department, 'department_name') or request.department,
