    def org_has_references(department):
        return any(frappe.db.exists(doctype, {'department': department}) for doctype in [PR, WF, INST, HIST])


    def org_flag(value):
        if value not in [0, 1, '0', '1', False, True]:
            fail('error.filters')
        return int(value)


    def org_rename(doctype, old_name, new_code):
        if old_name == new_code:
            return old_name
        if frappe.db.exists(doctype, new_code):
            fail('error.org_duplicate')
        new_name = frappe.rename_doc(doctype, old_name, new_code, ignore_permissions=True, show_alert=False, rebuild_search=False)
        # User Permission.for_value is Data, so Frappe's Link-field rename cannot update it.
        for permission in frappe.get_all('User Permission', filters={'allow': doctype, 'for_value': old_name}, fields=['name']):
            frappe.db.set_value('User Permission', permission.name, 'for_value', new_name)
        return new_name


    def validate_org_doc(doc):
        user = actor()
        org_admin(user)
        old = doc.get_doc_before_save()
        doc.active = org_flag(doc.active)
        if doc.doctype == 'Company':
            code = checked_text(doc.company_code, 50, True)
            doc.company_code = code
            doc.company_name = checked_text(doc.company_name, 140, True)
            for item in [('short_name', 140), ('tax_code', 140), ('phone', 50), ('email', 140), ('address', 2000)]:
                doc.set(item[0], checked_text(doc.get(item[0]), item[1]))
            if old:
                org_company_scope(user, old.name)
                if code != old.company_code or doc.name != old.name:
                    fail('error.org_code_locked')
            elif not super_user(user):
                fail('error.permission')
            elif frappe.db.exists('Company', code):
                fail('error.org_duplicate')
        elif doc.doctype == 'Department':
            code = checked_text(doc.department_code, 50, True)
            doc.department_code = code
            doc.department_name = checked_text(doc.department_name, 140, True)
            org_company_scope(user, doc.company)
            if old:
                org_company_scope(user, old.company)
                if code != old.department_code or doc.name != old.name:
                    fail('error.org_code_locked')
                if old.company != doc.company and org_has_references(old.name):
                    fail('error.org_department_linked')
            elif frappe.db.exists('Department', code):
                fail('error.org_duplicate')
            if doc.active and not frappe.db.get_value('Company', doc.company, 'active'):
                fail('error.org_company_inactive')
        else:
            fail('error.filters')


    def org_save(data):
        user = actor()
        doctype = org_kind(data)
        org_admin(user)
        name = checked_text(data.get('name'), 140)
        if name:
            result = org_get({'kind': data.get('kind'), 'name': name})
            if str(result['modified']) != str(data.get('expected_modified') or ''):
                fail('error.org_conflict')
            doc = frappe.get_doc(doctype, name)
            keys = ['short_name', 'company_name', 'tax_code', 'phone', 'email', 'address', 'active'] if doctype == 'Company' else ['department_name', 'company', 'active']
            code_key = 'company_code' if doctype == 'Company' else 'department_code'
            new_code = checked_text(data.get(code_key) or doc.get(code_key), 50, True)
            if new_code != doc.get(code_key):
                if doctype == 'Company':
                    org_company_scope(user, name)
                else:
                    org_company_scope(user, doc.company)
                name = org_rename(doctype, name, new_code)
                doc = frappe.get_doc(doctype, name)
            for key in keys:
                if key in data:
                    doc.set(key, data[key])
            doc.save(ignore_permissions=True)
        else:
            code_key = 'company_code' if doctype == 'Company' else 'department_code'
            code = checked_text(data.get(code_key), 50, True)
            if frappe.db.exists(doctype, code):
                fail('error.org_duplicate')
            values = {key: data.get(key) for key in (['short_name', 'company_name', 'tax_code', 'phone', 'email', 'address'] if doctype == 'Company' else ['department_name', 'company'])}
            doc = frappe.get_doc({'doctype': doctype, code_key: code, 'active': 1, **values})
            doc.insert(ignore_permissions=True)
        return org_values(doc)


    def org_deactivate(data):
        doc_data = org_get(data)
        if str(doc_data['modified']) != str(data.get('expected_modified') or ''):
            fail('error.org_conflict')
        doc = frappe.get_doc(org_kind(data), doc_data['name'])
        doc.active = 0
        doc.save(ignore_permissions=True)
        return org_values(doc)


    def read_rows(data):
        user = actor()
        start = check_date(data.get('from'))
        end = check_date(data.get('to'))
        if start and end and start > end:
            fail('error.filters')
        query = checked_text(data.get('query'), 100).lower()
        if data.get('status') and data.get('status') not in ['Draft', 'Pending Workflow Selection', 'Pending Stock Check', 'Pending Purchasing', 'Pending Approval', 'Approved', 'Closed', 'Returned', 'Rejected', 'Cancelled']:
            fail('error.filters')
        filters = {}
        for field in ['company', 'department', 'status']:
            if data.get(field):
                filters[field] = data.get(field)
        fields = ['name', 'company', 'department', 'requester', 'requester_name', 'purpose', 'status', 'priority', 'purchase_type', 'currency', 'request_date', 'required_date', 'final_total', 'estimated_total', 'priced_at', 'received_at', 'received_by', 'current_instance', 'modified', 'revision']
        rows = []
        for row in frappe.get_all(PR, filters=filters, fields=fields, limit_page_length=0):
            # Canonical permission runs before filtering, totals and pagination.
            if not can_read(user, row):
                continue
            date = str(row.get('request_date') or '')[:10]
            if (start and date < start) or (end and date > end):
                continue
            if query and not any(query in str(row.get(field) or '').lower() for field in ['name', 'purpose', 'requester_name']):
                continue
            rows.append(row)
        unpriced_names = [row.name for row in rows if not row.get('priced_at')]
        estimated_totals = {name: 0 for name in unpriced_names}
        if unpriced_names:
            items = frappe.get_all('PA Purchase Request Item',
                filters={'parent': ['in', unpriced_names]},
                fields=['parent', 'quantity', 'has_estimated_price', 'estimated_unit_price', 'estimated_vat_percent'],
                limit_page_length=0)
            for line in items:
                amounts = estimate_line_amounts(
                    line.get('quantity'), line.get('estimated_unit_price'),
                    line.get('estimated_vat_percent'), line.get('has_estimated_price'))
                estimated_totals[line.parent] = estimated_totals.get(line.parent, 0) + amounts['total']
        for row in rows:
            if row.get('priced_at'):
                row['amount'] = row.get('final_total') or 0
            else:
                row['estimated_total'] = estimated_totals.get(row.name, 0) / 100
                row['amount'] = row['estimated_total']
        return rows


    def read_history(rows):
        names = [row.name for row in rows]
        return frappe.get_all(HIST, filters={'request': ['in', names]}, fields=['name', 'request', 'creation', 'action', 'actor', 'actor_name', 'comment', 'step_order'], limit_page_length=0) if names else []


    def queue_matches(row, queue, history, user):
        if queue == 'all':
            return True
        if queue == 'mine':
            return row.requester == user
        if queue in ['approved_by_me', 'rejected_by_me']:
            action = 'Approve' if queue == 'approved_by_me' else 'Reject'
            return any(h.request == row.name and h.actor == user and h.action == action for h in history)
        if queue == 'received':
            return row.status == 'Closed' and row.received_by == user
        if queue in ['selection', 'stock_check', 'purchasing', 'approvals', 'receiving']:
            action = {'selection': 'select_workflow', 'stock_check': 'stock_check', 'purchasing': 'finalize', 'approvals': 'approve', 'receiving': 'receive'}[queue]
            return action in request_actions(frappe.get_doc(PR, row.name))
        fail('error.filters')

    def checked_queue(data, user):
        queue = data.get('queue') or 'all'
        capability = {'approvals': 'approvals', 'approved_by_me': 'approvals', 'rejected_by_me': 'approvals', 'purchasing': 'purchasing', 'receiving': 'receiving', 'received': 'receiving', 'stock_check': 'stock_check', 'selection': 'selection'}
        if queue not in ['all', 'mine'] and queue not in capability:
            fail('error.filters')
        if queue in capability and not read_capabilities(user)[capability[queue]]:
            fail('error.permission')
        return queue


    def list_requests(data):
        user = actor()
        try:
            page = max(0, min(int(data.get('page') or 0), 10000))
        except Exception:
            fail('error.required')
        queue = checked_queue(data, user)
        sort = data.get('sort') or 'modified'
        direction = data.get('direction') or 'desc'
        if sort not in ['modified', 'name', 'request_date', 'required_date', 'amount'] or direction not in ['asc', 'desc']:
            fail('error.filters')
        rows = read_rows(data)
        history = read_history(rows) if queue in ['approved_by_me', 'rejected_by_me'] else []
        visible = [row for row in rows if queue_matches(row, queue, history, user)]
        visible = sorted(visible, key=lambda row: (row.get(sort) or (0 if sort == 'amount' else ''), row.name), reverse=direction == 'desc')
        total = len(visible)
        return {'data': visible[page * 25:(page + 1) * 25], 'has_more': total > (page + 1) * 25, 'page': page, 'total': total, 'total_pages': (total + 24) // 25}


    def get_dashboard(data):
        user = actor()
        rows = read_rows(data)
        history = read_history(rows)
        capabilities = read_capabilities(user)
        metrics = {'mine': len([r for r in rows if r.requester == user]), 'returned_mine': len([r for r in rows if r.requester == user and r.status == 'Returned'])}
        for queue, capability in [('selection', 'selection'), ('stock_check', 'stock_check'), ('approvals', 'approvals'), ('approved_by_me', 'approvals'), ('rejected_by_me', 'approvals'), ('purchasing', 'purchasing'), ('receiving', 'receiving'), ('received', 'receiving')]:
            if capabilities[capability]:
                metrics[queue] = len([r for r in rows if queue_matches(r, queue, history, user)])
        totals = {}
        for row in rows:
            totals[row.company] = totals.get(row.company, 0) + row.amount
        recent = sorted(rows, key=lambda row: (str(row.modified or ''), row.name), reverse=True)[:10]
        activity = sorted(history, key=lambda row: (str(row.creation or ''), row.name), reverse=True)[:20]
        return {'metrics': metrics, 'recent': recent, 'activity': activity, 'company_totals': [{'company': company, 'company_name': frappe.db.get_value('Company', company, 'company_name') or company, 'amount': amount} for company, amount in sorted(totals.items())]}


    def workflow_options(data):
