    def workflow_assignee_options(company, department):
        workflow_admin_scope(actor(), company, department)
        target = frappe.get_doc({'doctype': PR, 'company': company, 'department': department})
        users = [row for row in frappe.get_all('User', filters={'enabled': 1}, fields=['name', 'full_name'], limit_page_length=0) if row.name != 'Guest' and frappe.call('purchase_approval.workflow_runtime.bridge', action='eligible_user', user=row.name, request=target)]
        names = [row.name for row in users]
        role_names = []
        for row in frappe.get_all('Has Role', filters={'parenttype': 'User', 'parent': ['in', names]}, fields=['role'], limit_page_length=0) if names else []:
            if row.role not in role_names and frappe.db.exists('Role', {'name': row.role, 'disabled': 0}):
                role_names.append(row.role)
        return {'users': users, 'roles': sorted(role_names)}


    def workflow_assignees(data):
        options = workflow_assignee_options(data.get('company'), data.get('department'))
        users = options['users']
        roles = options['roles']
        query = checked_text(data.get('query'), 100).lower()
        page = workflow_page(data)
        visible = sorted([row for row in users if not query or query in row.name.lower() or query in str(row.full_name or '').lower()], key=lambda row: (str(row.full_name or '').lower(), row.name))
        return {'users': [{'name': row.name, 'full_name': row.full_name or row.name} for row in visible[page * 20:(page + 1) * 20]], 'roles': roles, 'page': page, 'has_more': len(visible) > (page + 1) * 20}


    def workflow_flag(value):
        if value not in [0, 1, '0', '1']:
            fail('error.required')
        return int(value)


    def save_approval_workflow(data):
        user = actor()
        require_role(user, 'PA Company Admin')
        company = checked_text(data.get('company'), 140, True)
        department = checked_text(data.get('department'), 140) or None
        workflow_admin_scope(user, company, department)
        options = workflow_assignee_options(company, department)
        user_names = [row.name for row in options['users']]
        roles = options['roles']
        if data.get('currency', 'VND') != 'VND':
            fail('error.required')
        steps = data.get('steps')
        if not isinstance(steps, list) or not steps or len(steps) > 30:
            fail('error.workflow_order')
        normalized = []
        for index, step in enumerate(steps):
            if not isinstance(step, dict):
                fail('error.workflow_order')
            kind = step.get('step_type')
            source = step.get('approver_source')
            assigned_user = checked_text(step.get('approver_user'), 140) if source == 'User' else ''
            assigned_role = checked_text(step.get('approver_role'), 140) if source == 'Role' else ''
            if ((source == 'User' and assigned_user not in user_names) or (source == 'Role' and assigned_role not in roles) or source not in ['User', 'Role', 'Department Manager']):
                fail('error.workflow_assignee')
            method = step.get('approval_method') if kind == 'Quote Approval' else 'Any'
            if method not in ['Any', 'All']:
                fail('error.workflow_order')
            normalized.append({'step_order': index + 1, 'step_name': checked_text(step.get('step_name'), 140, True), 'step_type': kind, 'approval_method': method, 'approver_source': source, 'approver_user': assigned_user, 'approver_role': assigned_role, 'send_email': workflow_flag(step.get('send_email', 0))})
        frappe.call('purchase_approval.workflow_runtime.bridge', action='validate_steps', steps=normalized)
        selector_source = data.get('selector_source') or 'Role'
        selector_user = checked_text(data.get('selector_user'), 140) if selector_source == 'User' else ''
        selector_role = checked_text(data.get('selector_role'), 140) if selector_source == 'Role' else ''
        if (selector_source == 'User' and selector_user not in user_names) or (selector_source == 'Role' and selector_role not in roles) or selector_source not in ['User', 'Role']:
            fail('error.workflow_assignee')
        values = {'workflow_name': checked_text(data.get('workflow_name'), 140, True), 'company': company, 'department': department, 'currency': 'VND', 'is_active': workflow_flag(data.get('is_active', 1)), 'note': checked_text(data.get('note'), 2000), 'selector_source': selector_source, 'selector_user': selector_user, 'selector_role': selector_role, 'notify_requester': workflow_flag(data.get('notify_requester', 0))}
        if data.get('name'):
            doc = workflow_admin_doc(data['name'], True)
            if not data.get('expected_modified') or str(doc.modified) != str(data['expected_modified']):
                fail('error.conflict')
            for key in values:
                doc.set(key, values[key])
            doc.set('steps', normalized)
            doc.save(ignore_permissions=True)
        else:
            key = checked_text(data.get('idempotency_key'), 32, True).lower()
            if len(key) != 32 or any(c not in '0123456789abcdef' for c in key):
                fail('error.idempotency')
            name = 'PAWF-' + key
            query_lock('select name from `tabCompany` where name=%s for update', (company,))
            if frappe.db.exists(WF, name):
                existing = workflow_admin_doc(name, True)
                same_steps = [{field: step.get(field) or '' for field in ['step_name', 'step_type', 'approval_method', 'approver_source', 'approver_user', 'approver_role', 'send_email']} for step in existing.steps]
                requested_steps = [{field: step.get(field) or '' for field in ['step_name', 'step_type', 'approval_method', 'approver_source', 'approver_user', 'approver_role', 'send_email']} for step in normalized]
                if existing.owner != user or any((existing.get(field) or '') != (values[field] or '') for field in values) or same_steps != requested_steps:
                    fail('error.idempotency')
                return workflow_admin_result(existing)
            doc = frappe.get_doc({'doctype': WF, **values, 'steps': normalized})
            doc.insert(ignore_permissions=True, set_name=name)
        return workflow_admin_result(doc)

    def validate_supplier(doc):
        require_role(actor(), 'PA Company Admin')
        if not doc.companies:
            fail('error.required')
        old = doc.get_doc_before_save()
        if old:
            for row in old.companies:
                require_scope(actor(), row.company)
        for row in doc.companies:
            require_scope(actor(), row.company)


    def cancel_notifications(instance_name):
        for row in frappe.get_all('PA Notification Outbox', filters={'instance': instance_name, 'status': 'Pending'}, fields=['name']):
            frappe.db.set_value('PA Notification Outbox', row.name, 'status', 'Cancelled')


    def notify_step(request, instance):
        if frappe.call('purchase_approval.workflow_runtime.bridge', action='is_modern', request=request):
            current = frappe.call('purchase_approval.workflow_runtime.bridge', action='active_step', instance=instance)
            if current:
                frappe.call('purchase_approval.workflow_runtime.bridge', action='enqueue', request=request, instance=instance, step=current)
            return
        for row in instance.assignees:
            if row.step_order == instance.current_sequence and row.status == 'Pending':
                key = instance.name + ':' + str(row.step_order) + ':' + row.user
                existing = frappe.db.get_value('PA Notification Outbox', {'notification_key': key}, ['name', 'status'], as_dict=True)
                if existing:
                    if existing.status == 'Cancelled':
                        frappe.db.set_value('PA Notification Outbox', existing.name, 'status', 'Pending')
                    continue
                outbox = frappe.get_doc({'doctype': 'PA Notification Outbox', 'request': request.name, 'instance': instance.name, 'step_order': row.step_order, 'recipient': row.user, 'notification_key': key, 'subject': t('notification.subject') + ' ' + request.name, 'body': t('notification.body'), 'status': 'Pending'})
                outbox.insert(ignore_permissions=True)

    def notification_worker():
        if not frappe.db.get_single_value('PA Settings', 'email_enabled'):
            return
        for row in frappe.get_all('PA Notification Outbox', filters={'status': 'Pending', 'attempts': ['<', 5]}, fields=['name'], limit_page_length=100):
            query_lock('select name from `tabPA Notification Outbox` where name=%s for update', (row.name,))
            outbox = locked_doc('PA Notification Outbox', row.name)
            if outbox.status != 'Pending':
                continue
            instance = frappe.get_doc(INST, outbox.instance)
            request = frappe.get_doc(PR, outbox.request)
            active = request.status == 'Pending Approval' and instance.status == 'Pending' and request.current_instance == instance.name and instance.current_sequence == outbox.step_order and eligible(outbox.recipient, request) and any(a.user == outbox.recipient and a.step_order == outbox.step_order and a.status == 'Pending' for a in instance.assignees)
            if not active:
                outbox.status = 'Cancelled'
            else:
                outbox.attempts = int(outbox.attempts or 0) + 1
                try:
                    url = frappe.utils.get_url('/purchase-approval?request=' + request.name)
                    frappe.sendmail(recipients=[outbox.recipient], subject=outbox.subject, message=frappe.utils.escape_html(outbox.body) + '<br><a href="' + frappe.utils.escape_html(url) + '">' + frappe.utils.escape_html(request.name) + '</a>')
                    outbox.status = 'Sent'
                    outbox.sent_at = frappe.utils.now()
                    outbox.last_error = None
                except Exception:
                    outbox.last_error = t('error.email')
            outbox.save(ignore_permissions=True)


    def dispatch(command):
        user = actor()
        if not user or user == 'Guest':
            fail('error.permission')
        raw = frappe.form_dict.get('payload') or '{}'
        try:
            parsed = json.loads(raw) if isinstance(raw, str) else raw
            if not isinstance(parsed, dict):
                fail('error.required')
            data = dict(parsed)
        except Exception:
            fail('error.required')
        if command == 'create_purchase_request':
            return create_request(data)
        if command == 'save_purchase_request':
            return save_request(data)
        if command == 'submit_purchase_request':
            return submit_request(data)
        if command == 'choose_approval_workflow':
            request = lock_request(data.get('name'), data)
            old = document_values(request)
            frappe.call('purchase_approval.workflow_runtime.bridge', action='select', request=request, workflow_name=data.get('workflow'), user=user)
            audit(request, 'Select Workflow', old=old)
            return request_details(request)
        if command == 'confirm_stock_check':
            request = lock_request(data.get('name'), data)
            if request.status != 'Pending Stock Check':
                fail('error.status')
            instance = get_instance(request)
            current = frappe.call('purchase_approval.workflow_runtime.bridge', action='active_step', instance=instance)
            if not current or current.step_type != 'Stock Check':
                fail('error.status')
            old = document_values(request)
            comment = checked_text(data.get('comment'), 2000)
            frappe.call('purchase_approval.workflow_runtime.bridge', action='finish_step', request=request, instance=instance, user=user, comment=comment)
            audit(request, 'Stock Check', comment, old, current.step_order)
            return request_details(request)
        if command == 'finalize_purchase_request':
            return finalize_request(data)
        if command == 'approval_action':
            return approval_action(data)
        if command == 'receive_purchase_request':
            return receive_request(data)
        if command == 'cancel_purchase_request':
            return cancel_request(data)
        if command == 'reassign_approver':
            return reassign(data)
        if command == 'get_context':
            return get_context(data)
        if command == 'get_purchase_request':
            return request_details(lock_request(data.get('name'), {}, False))
        if command == 'list_purchase_requests':
            return list_requests(data)
        if command == 'get_dashboard':
            return get_dashboard(data)
        if command == 'workflow_options':
            return workflow_options(data)
        if command == 'item_suggestions':
            return item_suggestions(data)
        if command == 'list_approval_workflows':
            return list_approval_workflows(data)
        if command == 'get_approval_workflow':
            return workflow_admin_result(workflow_admin_doc(data.get('name')))
        if command == 'workflow_assignees':
            return workflow_assignees(data)
        if command == 'save_approval_workflow':
            return save_approval_workflow(data)
        if command == 'list_organizations':
            return org_list(data)
        if command == 'get_organization':
            return org_get(data)
        if command == 'save_organization':
            return org_save(data)
        if command == 'deactivate_organization':
            return org_deactivate(data)
        fail('error.status')

    result = dispatch('save_approval_workflow')
    frappe.response['message'] = result

pa_execute()
